const api=async p=>{const r=await fetch(p,{cache:'no-store'});if(!r.ok)throw Error(`${r.status}`);return r.json()};
const state={view:'home',today:{},recent:[],body:[],diet:[],training:[],movements:[],dictionary:[],movementGroups:[],movementSelection:'',movementHistory:null,movementUsage:{},usageLoaded:false,selectedBodyPart:null,page:1,syncStatus:null,archiveHealth:null,dataCheck:null,dataCheckOverlayOpen:false,saving:false,composing:false,trainingQuery:'',trainingOrder:'recent',movementQuery:'',routeParams:{},routeState:null,hoverTimer:null,hoverNode:null,movementMerge:null,buildInfo:null,formalSemanticPreview:null,formalSemanticBusy:false};
const main=$('#main'),root=$('#overlay-root'),toast=$('#toast');
const guardianNumberOrNull=value=>{const number=Number(value);return Number.isFinite(number)?number:null};
const guardianCompact=value=>Number(value).toFixed(2).replace(/\.00$/,'').replace(/(\.\d)0$/,'');
const guardianDateOf=record=>String(record?.Date||record?.date||'').slice(0,10);
const guardianBodyPart=value=>{const key=String(value||'').toLowerCase();if(/chest|pec|胸/.test(key))return'chest';if(/back|lat|pull|背/.test(key))return'back';if(/shoulder|delt|肩/.test(key))return'shoulders';if(/arm|bicep|tricep|肱|手臂/.test(key))return'arms';if(/leg|glute|quad|hamstring|calf|腿|臀/.test(key))return'legs';return'full_body'};
function buildHomeEntrySummary({today={},body=[],training=[],now=new Date()}={}){const hour=now.getHours(),greeting=hour<11?'GOOD MORNING':hour<18?'GOOD AFTERNOON':'GOOD EVENING',todayWeight=guardianNumberOrNull(today?.body?.['Weight (kg)']),dated=body.map(record=>({date:guardianDateOf(record),weight:guardianNumberOrNull(record?.['Weight (kg)'])})).filter(item=>item.date&&item.weight!==null).sort((a,b)=>a.date.localeCompare(b.date)),weight=todayWeight??dated.at(-1)?.weight??null,prefix=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`,month=dated.filter(item=>item.date.startsWith(prefix)),delta=month.length>1?month.at(-1).weight-month[0].weight:null,recent=[...training].sort((a,b)=>guardianDateOf(b).localeCompare(guardianDateOf(a)))[0];return{greeting,weightText:weight===null?'':`Latest weight · ${guardianCompact(weight)} kg`,monthTrendText:delta===null?'':`This month · ${delta>0?'+':''}${guardianCompact(delta)} kg`,recentTrainingText:recent?`Recent training · ${recent.Split||recent.split||guardianDateOf(recent)}`:''}}
function buildBodyRegionSummaries(movements=[]){const labels={shoulders:'Shoulders',chest:'Chest',arms:'Arms',back:'Back',legs:'Legs'};return Object.entries(labels).map(([key,label])=>{const matching=movements.filter(item=>guardianBodyPart(item.muscle_group)===key),representative=matching.sort((a,b)=>Number(b.history_count||0)-Number(a.history_count||0))[0];return{key,label,count:matching.length,sessionCount:matching.reduce((sum,item)=>sum+Number(item.history_count||0),0),representativeMovementId:representative?.movement_id||'',representativeMovementName:representative?.display_name||representative?.english_name||''}})}
function buildMovementPresentationSummary(payload={}){const movement=payload.movement||{},history=Array.isArray(payload.progress_history)?payload.progress_history:[],latest=history[0],metrics=latest?.metrics,useLoad=Number(metrics?.max_weight||0)>0,metric=record=>useLoad?Number(record?.metrics?.max_weight||0):Number(record?.metrics?.total_reps||0),best=history.reduce((max,record)=>Math.max(max,metric(record)),0),unit=useLoad?'kg':'reps';return{movementId:movement.movement_id||'',movementName:movement.display_name||movement.english_name||'',bodyPart:guardianBodyPart(movement.muscle_group),progressText:latest&&metrics?.has_structured_sets?`Latest · ${guardianCompact(metric(latest))} ${unit}`:'',bestText:best>0?`Best · ${guardianCompact(best)} ${unit}`:''}}
function buildTrainingSaveSummary(result={}){return{recordId:result.record_id||'',date:result.date||'',splitLabel:result.split_label||'',movementCountText:Number(result.movement_count||result.saved_movements||0)>0?`${Number(result.movement_count||result.saved_movements)} movements`:'',setCountText:Number(result.working_sets||0)>0?`${Number(result.working_sets)} working sets`:'',personalRecords:Array.isArray(result.personal_records)?result.personal_records.filter(item=>item?.newPr===true):[]}}
function buildDietStatus(record={},targets={}){const calories=guardianNumberOrNull(record['Calories (kcal)']??record.calories),target=guardianNumberOrNull(targets.calories??targets['Calories (kcal)']);if(calories===null||target===null||target<=0)return null;const delta=calories-target;return{label:Math.abs(delta)<=target*.05?'CALORIE TARGET MET':delta<0?'BELOW CALORIE TARGET':'ABOVE CALORIE TARGET',detail:`${guardianCompact(calories)} / ${guardianCompact(target)} kcal`}}
function buildWeightMilestone({current,previous,target,targetId='weight-goal'}={}){const values=[current,previous,target].map(guardianNumberOrNull);if(values.some(value=>value===null))return null;const[currentWeight,previousWeight,targetWeight]=values,crossed=previousWeight>targetWeight?currentWeight<=targetWeight:previousWeight<targetWeight?currentWeight>=targetWeight:false;if(!crossed)return null;return{message:`Target reached · ${guardianCompact(currentWeight)} kg`,dedupeKey:`weight-milestone:${targetId}:${guardianCompact(targetWeight)}`}}
function buildStructuredAnalysisSummary(requests=[],previews=[]){const list=(Array.isArray(requests)?requests:[requests]).filter(Boolean),types=[...new Set(list.flatMap(request=>(request.datasets||[]).map(dataset=>dataset.type).filter(Boolean)))],count=(Array.isArray(previews)?previews:[previews]).reduce((sum,preview)=>sum+Number(preview?.preview?.record_count||preview?.record_count||0),0);return{movementName:types.length?types.join(' · '):'Structured archive',progressText:count>0?`${count} records prepared`:'',bestText:list.length>0?`${list.length} read-only package${list.length===1?'':'s'}`:''}}
let guardianIntentSequence=0;
function emitGuardianIntent(type,summary={},options={}){const detail={type,summary,id:options.id||`${type}:${++guardianIntentSequence}`,...options};window.__fitnessLedgerGuardianPendingIntent=window.__fitnessLedgerGuardianPet?null:detail;window.dispatchEvent(new CustomEvent('fitness-ledger-pet:intent',{detail}));return detail.id}
function finishGuardianIntent(id,reason='completed'){if(window.__fitnessLedgerGuardianPendingIntent?.id===id)window.__fitnessLedgerGuardianPendingIntent=null;window.dispatchEvent(new CustomEvent('fitness-ledger-pet:intent',{detail:{id,phase:'finish',reason}}))}
function publishGuardianBodyRegions(){const regions=buildBodyRegionSummaries(state.movements);window.__fitnessLedgerGuardianBodyRegions=regions;window.dispatchEvent(new CustomEvent('fitness-ledger-pet:body-regions',{detail:{regions}}))}
function emitGuardianRouteSummary(){if(state.view==='home')emitGuardianIntent('home-entry',buildHomeEntrySummary(state),{id:`home:${state.today?.date||'empty'}`});if(state.view==='diet'){const status=buildDietStatus(state.today?.diet||{},state.today?.diet_targets||state.today?.targets?.diet||{});if(status)emitGuardianIntent('diet-status',status,{id:`diet:${state.today?.date||'today'}`})}}
function emitGuardianWeightMilestone(){const target=state.today?.weight_target??state.today?.targets?.weight,current=Number(state.body?.[0]?.['Weight (kg)']),previous=Number(state.body?.[1]?.['Weight (kg)']),summary=buildWeightMilestone({current,previous,target,targetId:state.today?.weight_target_id||'weight-goal'});if(!summary)return;try{if(sessionStorage.getItem(summary.dedupeKey))return;sessionStorage.setItem(summary.dedupeKey,'1')}catch{}emitGuardianIntent('weight-milestone',summary,{id:summary.dedupeKey})}
const showToast=t=>{toast.textContent=t;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)};
const dateOf=r=>String(r.Date||r.date||'').slice(0,10), value=(o,...keys)=>keys.map(k=>o?.[k]).find(v=>v!==undefined&&v!==null&&v!=='')??'-';
function buildIdentityLabel(info){const status=String(info?.status||'UNKNOWN').toUpperCase(),shortSha=info?.short_sha||'';if(status==='PUBLISHED')return `FORMAL · ${shortSha} · PUBLISHED`;if(status==='PREVIEW')return `PREVIEW · ${info?.branch||'WORKTREE'} · ${shortSha||'UNKNOWN'}${info?.dirty===true?' · DIRTY':''}`;if(status==='UNVERIFIED')return `FORMAL · ${shortSha||'UNKNOWN'} · UNVERIFIED`;return 'BUILD UNKNOWN'}
function renderBuildIdentity(){const button=$('[data-build-identity]');if(!button)return;const info=state.buildInfo||{};button.dataset.buildStatus=String(info.status||'UNKNOWN').toLowerCase();button.querySelector('.build-identity-label').textContent=buildIdentityLabel(info);button.title=info.dirty===true?'Preview 工作区存在未提交修改':`运行版本：${String(info.status||'UNKNOWN').toUpperCase()}`}
async function loadBuildInfo(){try{state.buildInfo=await api('/api/build-info')}catch{state.buildInfo={status:'UNKNOWN',mode:'unknown'}}renderBuildIdentity()}
function buildIdentityDetails(){const info=state.buildInfo||{},rows=[['运行模式',info.mode||'unknown'],['状态',info.status||'UNKNOWN'],['完整 Commit SHA',info.commit_sha||'不可用'],['来源分支',info.branch||'不可用'],['部署生成时间',info.generated_at||'不可用'],['服务启动时间',info.server_started_at||'不可用'],['部署时 main SHA',info.main_sha||'不可用'],['部署时 origin/main SHA',info.origin_main_sha||'不可用'],['Push 已验证',info.push_verified===true?'是':info.push_verified===false?'否':'不可用'],['Preview 工作区',info.dirty===true?'DIRTY / 有未提交修改':info.dirty===false?'CLEAN / 干净':'不可用'],['Tag',info.tag||'无']];return `<div class="build-identity-details"><div class="build-identity-status"><span class="eyebrow">RUNTIME IDENTITY</span><h3>${esc(buildIdentityLabel(info))}</h3><p>这是当前运行服务的部署身份，不是后台实时远端监控。</p></div><dl>${rows.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>${info.commit_sha?`<button class="btn build-copy-sha" data-build-copy-sha>复制完整 SHA</button>`:''}</div>`}
function openBuildIdentity(){const button=$('[data-build-identity]');if(button)button.setAttribute('aria-expanded','true');modal('运行版本与部署身份',buildIdentityDetails(),{light:true,actions:'<button class="btn btn-primary" data-close>关闭</button>'})}

function statusPanel(){const t=state.today,b=t.body||{},d=t.diet||{},tr=t.training||{};return `<section class="status-panel"><span class="eyebrow">TODAY / STATUS</span><h2>${esc(t.date||'No record')}</h2><div class="status-row"><span>Weight 体重</span><strong>${esc(value(b,'Weight (kg)'))} kg</strong></div><div class="status-row"><span>Bowel 排便</span><strong>${esc(value(b,'Bowel Movement'))}</strong></div><div class="status-row"><span>Calories 热量</span><strong>${esc(value(d,'Calories (kcal)'))} kcal</strong></div><div class="status-row"><span>Training 分部</span><strong>${esc(value(tr,'split','Split'))}</strong></div><div class="status-row"><span>Cardio 有氧</span><strong>${esc(value(t,'cardio'))}</strong></div></section>`}
function renderArchiveHealth(){const nav=$('[data-health-nav-entry]'),marker=nav?.querySelector('.health-nav-status'),toolsStatus=$('[data-tools-health-status]'),health=state.archiveHealth,count=Number(health?.issue_count||0),needsReview=health?.status==='NEEDS_REVIEW'&&count>0,normalLabel='查看待处理的数据问题';if(nav&&marker){nav.hidden=!needsReview;marker.hidden=!needsReview;marker.className=`health-nav-status${needsReview?' needs-review':''}`;if(!needsReview){marker.textContent='';nav.removeAttribute('title');nav.setAttribute('aria-label',normalLabel)}else{marker.textContent=String(count);nav.title=`待处理数据问题：${count} 个`;nav.setAttribute('aria-label',`待处理数据问题：${count} 个`)}}if(toolsStatus){const unavailable=health?.status==='UNAVAILABLE',loading=!health?.status;toolsStatus.dataset.status=needsReview?'review':unavailable?'unavailable':loading?'loading':'ok';toolsStatus.textContent=needsReview?`${count} 项待处理`:unavailable?'检查暂不可用':loading?'正在检查':'当前无需处理'}}
