checksPage=function(){main.innerHTML=`<section class="page page-grid checks-page"><div class="content">${pageHeader('Data Check','检查未解决的数据问题；只有明确的 Open 入口会打开详情。')}<div class="toolbar check-filters"><button class="btn btn-primary is-selected" data-check-filter="all">全部问题 &nbsp; ${issues.length}</button><button class="btn" data-check-filter="high">高 2</button><button class="btn" data-check-filter="medium">中 3</button><button class="btn" data-check-filter="low">低 1</button></div><div class="table-wrap check-table-wrap"><table class="check-table"><thead><tr><th>级别</th><th>日期</th><th>区域</th><th>问题</th><th>建议处理</th><th>详情</th></tr></thead><tbody>${issues.map((x,i)=>`<tr data-severity="${x[0].toLowerCase()}"><td><span class="severity ${x[0].toLowerCase()}">${x[0]}</span></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td><td><button class="link issue-open" data-open-issue="${i}">Open</button></td></tr>`).join('')}</tbody></table></div><div class="records-status" aria-live="polite">显示 ${issues.length} 个本地问题</div></div><aside class="rail"><section class="rail-section" style="margin-top:0"><span class="eyebrow">处理原则</span><h2 style="font:400 24px var(--serif)">由你确认，再进行修正</h2><p>网页查看端只展示问题详情，不会自动修改本地数据。</p></section><section class="rail-section"><span class="eyebrow">状态说明</span><div class="state-stack" style="margin-top:16px"><div class="state error">High · 优先核对</div><div class="state warning">Medium · 影响准确性</div><div class="state success">Low · 提示性问题</div></div></section></aside></section>`}

const compactSearch=value=>String(value??'').normalize('NFKC').toLowerCase().replace(/[\s\-_./\\，。；、:：()（）]+/g,'');
function dateParts(value){const match=String(value??'').match(/(?:\d{4}[-/.])?(\d{1,2})[-/.](\d{1,2})/);return match?[Number(match[1]),Number(match[2])]:null}
function fuzzyMatch(record,query){const raw=String(query??'').trim();if(!raw)return true;const compact=compactSearch(JSON.stringify(record)),terms=raw.split(/\s+/).map(compactSearch).filter(Boolean);if(terms.every(term=>compact.includes(term)))return true;const wanted=dateParts(raw),actual=dateParts(dateOf(record));return Boolean(wanted&&actual&&wanted[0]===actual[0]&&wanted[1]===actual[1])}
function latestRecordDate(rows){return rows.reduce((latest,row)=>{const date=new Date(`${dateOf(row)}T00:00:00`);return Number.isNaN(date.valueOf())||date<latest?latest:date},new Date(0))}
function withinDays(row,days,rows){if(!days)return true;const latest=latestRecordDate(rows),date=new Date(`${dateOf(row)}T00:00:00`);return !Number.isNaN(date.valueOf())&&(latest-date)/86400000<days}
const selectedValue=id=>document.getElementById(id)?.value||'all';

quickPage=function(){main.innerHTML=`<section class="page entry-page entry-editorial"><header class="entry-header"><div class="entry-title-lockup"><span class="eyebrow">02 / DAILY ENTRY</span><h1 class="page-title"><span>Write</span> the day.</h1><p class="page-subtitle">Freeform first. <b>Structure follows</b> after review.</p><div class="entry-rule"><span>LOCAL NOTE</span><i></i><span>PRIVATE ARCHIVE</span></div></div><button class="home-text-link" data-go="home">← Back to Home</button></header><div class="entry-spread"><article class="capture"><span class="eyebrow">FREEFORM → STRUCTURED</span><h2>Raw first.<br><em>Structure second.</em></h2><textarea id="raw-entry" placeholder="写下今天的任何内容…"></textarea><div class="actions"><button class="btn btn-primary" id="parse">Parse & Review →</button><button class="btn btn-light" data-mock="Undo remains in the stable desktop app.">Undo last save</button></div><p class="phase">Read-only Web preview. Formal writes remain in the stable desktop app.</p></article><aside class="entry-aside">${statusPanel()}${recentPanel()}</aside></div></section>`}

function compactEntryAside(){const t=state.today,b=t.body||{},d=t.diet||{},tr=t.training||{};return `<aside class="entry-compact-aside"><section class="entry-today-compact material-frosted edge-highlight"><span class="receipt-pin" aria-hidden="true"></span><span class="eyebrow">LATEST ENTRY / ${esc(t.date||'NO RECORD')}</span><div class="today-weight"><strong>${esc(value(b,'Weight (kg)'))}</strong><small>kg</small></div><div class="today-facts"><span><b>${esc(value(d,'Calories (kcal)'))}</b> kcal</span><span><b>${esc(value(tr,'split','Split'))}</b> training</span><span><b>${esc(value(t,'cardio'))}</b> cardio</span><span><b>${esc(value(b,'Bowel Movement'))}</b> bowel</span></div></section><section class="entry-recent-compact archive-slip"><div class="rail-head"><span class="eyebrow">RECENT SAVED</span><button data-go="body">View all →</button></div>${state.recent.slice(0,2).map((r,i)=>`<div class="compact-record archive-card interactive-lift" style="--slip-index:${i}"><span>0${i+1}</span><div><strong>${esc(r.date)}</strong><small>${esc(r.weight||'—')} kg · ${esc(r.calories||'—')} kcal<br>${esc(r.split||'Rest')}</small></div><button data-record="${esc(r.date)}">Open</button></div>`).join('')}</section></aside>`}
quickPage=function(){main.innerHTML=`<section class="page entry-page entry-editorial entry-single-screen entry-workbench-page"><div class="entry-desk-atmosphere" aria-hidden="true"></div><header class="entry-header"><div class="entry-title-lockup"><span class="eyebrow">02 / DAILY ENTRY</span><h1 class="page-title"><span>Write</span> the day.</h1><p class="page-subtitle">Freeform first. <b>Structure follows</b> after review.</p><div class="entry-rule"><span>LOCAL NOTE</span><i></i><span>PRIVATE ARCHIVE</span></div></div><button class="home-text-link" data-go="home">← Back to Home</button></header><div class="entry-spread entry-workbench"><article class="capture material-slab edge-highlight"><span class="capture-tab">02 / LOCAL CAPTURE</span><span class="eyebrow">FREEFORM → STRUCTURED</span><h2>Raw first. <em>Structure second.</em></h2><textarea id="raw-entry" placeholder="写下今天的任何内容…"></textarea><div class="actions"><button class="btn btn-primary interactive-lift interactive-press" id="parse">Parse & Review <span>→</span></button><button class="btn btn-light material-control interactive-press" data-undo>Undo last save</button></div><p class="phase">Review first; confirmed saves create a local backup automatically.</p></article>${compactEntryAside()}<aside class="entry-save-float material-frosted"><i></i><div><span>LOCAL-FIRST</span><strong>Ready to capture</strong><small>Changes are saved only after Review.</small></div><b>✓</b></aside></div></section>`}

bodyPage=function(){main.innerHTML=`<section class="page archive-page body-archive"><div class="body-folio">BODY / LOCAL ARCHIVE / PRIVATE</div><div class="archive-heading">${pageHeader('Body Records','Daily measurements as personal body slips, with notes kept readable.')}</div><div class="body-controls-row"><div class="toolbar body-toolbar"><input class="control search" id="body-search" placeholder="Search notes or date..."><select class="control" id="body-time"><option value="0">All time</option><option value="7">Recent 7 days</option><option value="14">Recent 14 days</option><option value="30">Recent 30 days</option></select><select class="control" id="body-order"><option value="recent">Newest first</option><option value="oldest">Oldest first</option></select></div><div id="body-weight-slot" class="body-weight-slot"></div></div><div id="body-rows" class="body-ledger"></div>${pager()}</section>`;renderBodyRows()}
function stableHash(value){let hash=2166136261;for(const char of String(value||'')){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619)}return hash>>>0}
function bodySlipKey(record){return record.id||record.record_id||record.uuid||[dateOf(record),value(record,'Weight (kg)'),value(record,'Training'),value(record,'Cardio'),value(record,'Notes')].join('|')}
function bodySlipClasses(record,avoidTone=''){const tones=['tone-feature','tone-training','tone-rest','tone-cardio','tone-purple'],hash=stableHash(bodySlipKey(record)),baseIndex=hash%tones.length,tone=tones[baseIndex]===avoidTone?tones[(baseIndex+1)%tones.length]:tones[baseIndex],offset=Math.floor(hash/tones.length)%3;return `${tone} body-offset-${offset}`}
renderBodyRows=function(q=$('#body-search')?.value||''){const days=Number(selectedValue('body-time')||0);let rows=state.body.filter(r=>fuzzyMatch(r,q)).filter(r=>withinDays(r,days,state.body));if(selectedValue('body-order')==='oldest')rows=[...rows].reverse();let previousTone='';$('#body-rows').innerHTML=rows.map((r,i)=>{const training=String(value(r,'Training')),classes=bodySlipClasses(r,previousTone);previousTone=classes.split(' ')[0];return `<article class="body-slip ${classes}"><div class="body-slip-date"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(dateOf(r))}</strong></div><div class="body-slip-weight"><b>${esc(value(r,'Weight (kg)'))}</b><small>kg</small></div><div class="body-slip-meta"><span>Bowel <strong>${esc(value(r,'Bowel Movement'))}</strong></span><span>Training <strong>${esc(short(training,24))}</strong></span><span>Cardio <strong>${esc(short(value(r,'Cardio'),24))}</strong></span></div><div class="body-slip-copy"><p>${esc(short(value(r,'Notes'),160))}</p><button class="record-open" data-detail="body" data-index="${state.body.indexOf(r)}">Open record</button></div></article>`}).join('')||'<p class="empty-note">No body records match this search.</p>'}

dietPage=function(){main.innerHTML=`<section class="page archive-page diet-archive"><div class="archive-heading">${pageHeader('Diet Records','Energy and macros first. Full meals remain one deliberate click away.')}</div><div class="toolbar diet-toolbar"><input class="control search" id="diet-search" placeholder="Search notes, food or date..."><select class="control" id="diet-order"><option value="recent">Newest first</option><option value="oldest">Oldest first</option></select></div><div id="diet-rows" class="diet-slips"></div>${pager()}</section>`;renderDietRows()}
renderDietRows=function(q=$('#diet-search')?.value||''){let rows=state.diet.filter(r=>fuzzyMatch(r,q));if(selectedValue('diet-order')==='oldest')rows=[...rows].reverse();$('#diet-rows').innerHTML=rows.map((r,i)=>`<article class="diet-slip ${i%4===1?'slip-offset':''}"><span class="slip-index">${String(i+1).padStart(2,'0')}</span><h3>${esc(dateOf(r))}</h3><div class="macro-line"><strong>${esc(value(r,'Calories (kcal)'))}<small>kcal</small></strong><span>P ${esc(value(r,'Protein (g)'))}</span><span>C ${esc(value(r,'Carbs (g)'))}</span><span>F ${esc(value(r,'Fat (g)'))}</span></div><div class="diet-summary"><span>MEAL INDEX</span><p>${esc(short(value(r,'Food Summary'),68))}</p></div><button class="record-open" data-detail="diet" data-index="${state.diet.indexOf(r)}">Read detail</button></article>`).join('')||'<p class="empty-note">No diet records match this search.</p>'}

function movementArtFor(group){const key=String(group||'').toLowerCase();if(/shoulder|肩/.test(key))return'body-themes-v2/shoulders.png';if(/arms?|biceps|triceps|手臂|二头|三头/.test(key))return'body-themes-v2/arms.png';if(/back|pull|背/.test(key))return'body-themes-v2/back.png';if(/chest|胸/.test(key))return'body-themes-v2/chest.png';if(/leg|glute|lower|腿|臀/.test(key))return'body-themes-v2/legs.png';return'movement-art-core.png'}
function movementGroupClass(group){const key=String(group||'').toLowerCase();if(/leg|glute|lower|腿|臀/.test(key))return'group-legs';if(/shoulder|肩/.test(key))return'group-shoulders';if(/back|pull|背/.test(key))return'group-back';if(/chest|胸/.test(key))return'group-chest';if(/arms?|biceps|triceps|手臂|二头|三头/.test(key))return'group-arms';return'group-core'}
function layoutMovementMasonry(){const grid=$('.movement-groups');if(!grid)return;const groups=[...grid.children].filter(node=>node.classList.contains('movement-group'));groups.forEach(group=>group.style.gridRowEnd='auto');if(matchMedia('(max-width:1120px)').matches)return;const style=getComputedStyle(grid),rowHeight=parseFloat(style.gridAutoRows)||4,gap=parseFloat(style.rowGap)||14;groups.forEach(group=>{group.style.gridRowEnd=`span ${Math.max(1,Math.ceil((group.getBoundingClientRect().height+gap)/(rowHeight+gap)))}`})}
renderMovementDirectory=function(q=''){
  clearMovementIndexPreviousPreview();
  const target=$('#movement-list');if(!target)return;
  const usage=m=>state.movementUsage[String(m.movement_id||'')]?.count||0;
  const focus=m=>Number(m.focus_rank||0)>0||Boolean(m.pinned),rank=m=>Number(m.focus_rank||0)>0?Number(m.focus_rank):Number.MAX_SAFE_INTEGER;
  const rows=state.movements.filter(m=>usage(m)>0&&fuzzyMatch(m,q)).sort((a,b)=>Number(focus(b))-Number(focus(a))||rank(a)-rank(b)||usage(b)-usage(a)||String(a.display_name||'').localeCompare(String(b.display_name||''),'zh-CN'));
  const groups=new Map();for(const m of rows){const key=m.muscle_group||'Other';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(m)}
  const ordered=[...groups.entries()].sort((a,b)=>b[1].reduce((n,m)=>n+usage(m),0)-a[1].reduce((n,m)=>n+usage(m),0));
  target.innerHTML=ordered.map(([group,items],groupIndex)=>{
    const header=`<img class="movement-group-art" src="assets/${movementArtFor(group)}" alt="" aria-hidden="true"><header><span class="group-number">${String(groupIndex+1).padStart(2,'0')}</span><div><h2>${esc(groupLabel(group))}</h2><p>${esc(group)} · ${items.length} movements</p></div></header>`;
    return `<section class="movement-group group-${groupIndex%3} ${movementGroupClass(group)}">${header}<div class="movement-mosaic">${items.map((m,i)=>{const movementId=String(m.movement_id||''),name=m.display_name||m.english_name||movementId,count=usage(m),progressHistory=Array.isArray(state.movementUsage[movementId]?.payload?.progress_history)?state.movementUsage[movementId].payload.progress_history:[],hasPreview=Boolean(progressHistory[0]);return `<button class="movement-tile ${i===0&&count?'tile-lead':count>=4?'tile-wide':'tile-slip'} ${hasPreview?'has-index-previous-record':''}" data-select-movement-id="${esc(movementId)}" data-index-preview-movement-id="${esc(movementId)}">${m.pinned?'<span class="movement-focus-mark">★ FOCUS</span>':''}<span class="tile-count">${count} sessions</span>${hasPreview?'<span class="movement-index-preview-cue">HOLD · LAST SESSION</span>':''}<strong>${esc(name)}</strong><small>${esc(m.english_name&&m.english_name!==name?m.english_name:groupLabel(group))}</small><em>Open trajectory →</em></button>`}).join('')}</div></section>`
  }).join('')||'<p class="empty-note">No matching movements.</p>';
  const count=$('.result-count');if(count)count.textContent=`${rows.length} movements`;
  requestAnimationFrame(()=>requestAnimationFrame(layoutMovementMasonry));
}
loadMovementFocus=async function(movementId){state.movementSelection=String(movementId||'');main.innerHTML=`<section class="page movement-detail-page"><button class="movement-back" data-movement-index>← Movement Index</button><div id="movement-focus"><div class="loading-page"><i></i><p>Loading recorded history…</p></div></div></section>`;const focus=$('#movement-focus');try{let payload=state.movementUsage[String(movementId)]?.payload;if(!payload)payload=await api(`/api/movement-history?movement_id=${encodeURIComponent(movementId)}&limit=50`);state.movementHistory=payload;if(!payload.movement){navigate('movements',{}, {replace:true,context:null});return}const movement=payload.movement||{},history=payload.progress_history||payload.history||[],latest=history[0],earliest=history[history.length-1],art=movementArtFor(movement.muscle_group);focus.innerHTML=`<div class="movement-detail-compact"><img src="assets/${art}" alt="" aria-hidden="true"><div><span class="eyebrow">RECORDED TRAJECTORY</span><h1>${esc(movement.display_name||movementId)}</h1><p>${esc(movement.english_name||movement.muscle_group||'Recorded movement')}</p></div><div class="movement-detail-stats"><span><b>${history.length}</b> sessions</span><span><b>${esc(latest?.date||'—')}</b> latest</span><span><b>${esc(earliest?.date||'—')}</b> first</span></div></div><div class="trajectory-heading"><span class="eyebrow">PROGRESSION / NEWEST FIRST</span><h2>Training trajectory</h2><p>每次训练的负重、次数、组数和备注按时间展开。</p></div><div class="trajectory"><div class="trajectory-line"></div>${history.map((r,i)=>`<article class="trajectory-entry ${i===0?'is-latest':''}"><div class="trajectory-marker">${String(i+1).padStart(2,'0')}</div><button class="history-date history-date-link" data-training-date="${esc(r.date||'')}" data-training-movement-id="${esc(movement.movement_id||movementId)}"><strong>${esc(r.date||'?')}</strong><small>Day ${esc(r.training_day??'?')} ? Ex ${esc(r.order??'?')}</small></button><div class="history-content"><h3>${esc((r.sets_lines||[]).join(' · ')||'Recorded without structured sets')}</h3>${r.notes?`<p>${esc(r.notes)}</p>`:''}</div></article>`).join('')||'<div class="empty-copy"><h3>No history yet</h3><p>This movement exists in the dictionary but has no recorded sessions.</p></div>'}</div>`}catch{focus.innerHTML='<div class="empty-copy"><h3>History unavailable</h3><p>The local read-only service could not load this movement.</p></div>'}}

function movementRecordMetrics(record){let maxLoad=0,volume=0,totalReps=0,comparable=false;for(const line of record.sets_lines||[]){const pattern=/(\d+(?:\.\d+)?)\s*(?:kg)?\s*[×x*]\s*(\d+)\s*[×x*]\s*(\d+)/gi;let match;while((match=pattern.exec(line))){const load=Number(match[1]),reps=Number(match[2]),sets=Number(match[3]);if(reps<=0||sets<=0)continue;comparable=true;maxLoad=Math.max(maxLoad,load);volume+=load*reps*sets;totalReps+=reps*sets}if(/自重|body\s*weight|\bbw\b/i.test(line)){const body=line.match(/[×x*]\s*(\d+)\s*[×x*]\s*(\d+)/i);if(body){const reps=Number(body[1]),sets=Number(body[2]);if(reps>0&&sets>0){comparable=true;totalReps+=reps*sets;volume+=reps*sets}}}}return {maxLoad,volume,totalReps,comparable}}
function movementProgressChart(history){const available=history.slice(0,8).reverse().map(record=>({...record,...movementRecordMetrics(record)})).filter(record=>record.comparable);if(!available.length)return `<section class="movement-progress-panel is-empty"><div class="progress-copy"><span class="eyebrow">RECENT 8 / VISUAL SUMMARY</span><h2>Recent change</h2></div><p class="progress-empty-copy">No comparable structured data yet</p></section>`;const latestRecord=available.at(-1),useLoad=latestRecord.maxLoad>0,records=available.filter(record=>useLoad?record.maxLoad>0:record.maxLoad===0),values=records.map(record=>useLoad?record.maxLoad:record.totalReps),volumes=records.map(record=>record.volume),maxValue=Math.max(...values,1),maxVolume=Math.max(...volumes,1),left=48,right=682,width=right-left,step=records.length>1?width/(records.length-1):0;const points=records.map((record,index)=>`${left+index*step},${145-(values[index]/maxValue)*92}`).join(' '),bars=records.map((record,index)=>{const height=(volumes[index]/maxVolume)*70,x=left+index*step-12;return `<rect x="${x}" y="${160-height}" width="24" height="${height}" rx="4"></rect>`}).join(''),dots=records.map((record,index)=>`<circle cx="${left+index*step}" cy="${145-(values[index]/maxValue)*92}" r="5"></circle>`).join(''),labels=records.map((record,index)=>`<text x="${left+index*step}" y="194" text-anchor="middle">${esc(String(record.date||'').slice(5))}</text>`).join(''),latest=values.at(-1),previous=values.length>1?values.at(-2):null,delta=previous===null?null:Math.round((latest-previous)*10)/10;return `<section class="movement-progress-panel"><div class="progress-copy"><span class="eyebrow">RECENT 8 / VISUAL SUMMARY</span><h2>Recent change</h2><p>${useLoad?'折线为最高负重，柱形为估算训练容量。':'自重动作以总次数趋势显示，柱形同步表达训练工作量。'}</p></div><div class="progress-signal"><span>Latest</span><strong>${latest}${useLoad?' kg':' reps'}</strong>${delta===null?'':`<small class="${delta>0?'up':delta<0?'down':''}">${delta>0?'+':''}${delta} vs previous</small>`}</div><svg class="progress-chart" viewBox="0 0 730 220" role="img" aria-label="Recent movement progression"><g class="chart-grid"><line x1="48" y1="53" x2="682" y2="53"></line><line x1="48" y1="99" x2="682" y2="99"></line><line x1="48" y1="145" x2="682" y2="145"></line></g><g class="volume-bars">${bars}</g><polyline class="load-line" points="${points}"></polyline><g class="load-dots">${dots}</g><g class="chart-labels">${labels}</g></svg></section>`}
loadMovementFocus=async function(movementId){state.movementSelection=String(movementId||'');main.innerHTML=`<section class="page movement-detail-page"><button class="movement-back" data-movement-index>← Movement Index</button><div id="movement-focus"><div class="loading-page"><i></i><p>Loading recorded history…</p></div></div></section>`;const focus=$('#movement-focus');try{let payload=state.movementUsage[String(movementId)]?.payload;if(!payload)payload=await api(`/api/movement-history?movement_id=${encodeURIComponent(movementId)}&limit=50`);state.movementHistory=payload;if(!payload.movement){navigate('movements',{}, {replace:true});return}const movement=payload.movement||{},progressHistory=Array.isArray(payload.progress_history)?payload.progress_history:[],history=Array.isArray(payload.history)?payload.history:[],latest=progressHistory[0],earliest=progressHistory[progressHistory.length-1],art=movementArtFor(movement.muscle_group),groupClass=movementGroupClass(movement.muscle_group),display=movement.display_name||movementId,longClass=String(display).length>5?'is-long':'';focus.innerHTML=`<div class="movement-detail-compact ${groupClass} ${longClass}"><img class="movement-detail-art" src="assets/${art}" alt="" aria-hidden="true"><div class="movement-detail-title"><span class="eyebrow">RECORDED TRAJECTORY</span><h1>${esc(display)}</h1><p>${esc(movement.english_name||movement.muscle_group||'Recorded movement')}</p></div><div class="movement-detail-stats"><span><b>${progressHistory.length}</b> effective sessions</span><span><b>${esc(latest?.date||'—')}</b> latest</span><span><b>${esc(earliest?.date||'—')}</b> first</span></div></div>${movementProgressChart(progressHistory)}<div class="trajectory-heading"><span class="eyebrow">FULL HISTORY / NEWEST FIRST</span><h2>Training history</h2><p>完整动作历史保留所有实例；成长图表只读取有效轨迹。</p></div><div class="trajectory">${history.map((r,i)=>{const sets=(r.sets_lines||[]).filter(Boolean);return `<article class="trajectory-entry ${i===0?'is-latest':''} ${r.exclude_from_progress?'is-progress-excluded':''}"><button class="history-date history-date-link" data-training-date="${esc(r.date||'')}" data-training-movement-id="${esc(movement.movement_id||movementId)}"><strong>${esc(r.date||'?')}</strong>${r.exclude_from_progress?'<small>不计入成长轨迹</small>':''}</button><div class="history-content">${sets.length?`<h3>${esc(sets.join(' · '))}</h3>`:''}${r.notes?`<p>${esc(r.notes)}</p>`:''}</div></article>`}).join('')||'<div class="empty-copy"><h3>No history yet</h3><p>This movement exists in the dictionary but has no recorded sessions.</p></div>'}</div>`}catch{focus.innerHTML='<div class="empty-copy"><h3>History unavailable</h3><p>The local read-only service could not load this movement.</p></div>'}}

async function postApi(path,payload){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json().catch(()=>({error:'Invalid local service response.'}));if(!response.ok){const error=Error(data.error||`Request failed (${response.status})`);error.status=response.status;error.payload=data;throw error}return data}
