async function saveMovementHistory(){const form=$('#movement-history-form');if(!form)return;const values=Object.fromEntries(new FormData(form).entries()),progressToggle=form.elements.exclude_from_progress;if(progressToggle)values.exclude_from_progress=!progressToggle.checked;const button=$('[data-movement-history-save]');button.disabled=true;try{const result=await postApi('/api/movement-history/update',{movement_id:form.dataset.movementId,history_id:form.dataset.historyId,values});root.innerHTML='';if(result.status!=='NO_CHANGES')invalidateMovementUsage();await refreshWebState();await loadMovementFocus(state.movementSelection);showSaveReceipt(result)}catch(error){button.disabled=false;showSaveReceipt(null,error.message||'动作记录保存失败。')}}
