function renderRoute(route=parseRoute(),entryState=history.state||{}){if(route.view!=='guardian'){window.__fitnessLedgerGuardianPageCleanup?.();document.body.classList.remove('guardian-route')}const legacy=route.view==='checks'?'health':route.view==='export'?'export':route.view==='cloud-sync'?'sync':'';if(legacy)route={view:'tools',params:new URLSearchParams({panel:legacy})};state.view=route.view;state.routeParams=Object.fromEntries(route.params);state.routeState=entryState;resetRouteUiState();$$('.nav-item').forEach(b=>b.classList.toggle('is-active',b.dataset.view===state.view));const activeNav=document.querySelector('.nav-item.is-active');const navRail=activeNav?.parentElement;if(activeNav&&navRail&&navRail.scrollWidth>navRail.clientWidth)activeNav.scrollIntoView({block:'nearest',inline:'center'});window.scrollTo(0,0);({home:homePage,quick:quickPage,body:bodyPage,diet:dietPage,training:trainingPage,movements:movementPage,checks:checksPage,dictionary:dictionaryPage,tools:toolsPage,guardian:guardianPetPage}[state.view]||homePage)();window.dispatchEvent(new CustomEvent('fitness-ledger-pet:route-change',{detail:{view:state.view,panel:state.routeParams?.panel||null}}));queueMicrotask(emitGuardianRouteSummary);if(legacy==='health')queueMicrotask(openDataCheckOverlay)}
