function closeDataCheckOverlay(){state.dataCheckOverlayOpen=false;void window.__fitnessLedgerGuardianPet?.clearIntent?.('data-check-close');root.innerHTML=''}
checksPage=async function(){
  main.innerHTML='<div class="loading-page"><i></i><p>正在读取本地数据检查结果…</p></div>';
  const guardianCheckId=emitGuardianIntent('page-loading',{stage:'Scanning archive health'},{id:'data-check-page-active'});
  try{
    state.dataCheck=await api('/api/data-check');
    const rows=state.dataCheck.issues||[];
    const issueCount=rows.length;
    finishGuardianIntent(guardianCheckId);
    if(issueCount)emitGuardianIntent('needs-review',{message:'Archive health scan found unresolved items',countText:`${issueCount} ${issueCount===1?'issue':'issues'}`},{id:`data-check-page:${state.dataCheck.generated_at||issueCount}`});
    const stateLabel=issueCount?'NEEDS REVIEW':'ARCHIVE CLEAR';
    main.innerHTML=`<section class="page admin-page admin-checks-page checks-page checks-page-v6" data-check-count="${issueCount}" data-admin-template="collective-os-dashboard-v1"><button class="admin-back-link" data-tools-panel="overview">← Tools</button><header class="admin-page-header"><div><div class="admin-breadcrumb"><span>TOOLS</span><i>/</i><strong>ARCHIVE HEALTH</strong></div><h1>Data Check</h1><p>扫描本地记录的结构完整性。问题只进入 review queue，不会自动改写正式数据。</p></div><div class="admin-header-actions"><span class="admin-status-badge ${issueCount?'is-review':'is-clear'}"><i></i>${stateLabel}</span><button class="admin-button admin-button-outline" data-tools-panel="sync">Cloud Sync <span>→</span></button></div></header><section class="admin-health-summary"><div><span class="admin-kicker">SCAN RESULT</span><h2>${issueCount?'需要你的判断':'当前无需处理'}</h2><p>${issueCount?'按日期和区域打开问题，修正后再确认。':'最近一次扫描没有未确认问题；检查入口保持安静。'}</p></div><dl class="admin-stat-grid"><div><dt>UNRESOLVED</dt><dd>${issueCount}</dd></div><div><dt>ACKNOWLEDGED</dt><dd>${state.dataCheck.acknowledged_count||0}</dd></div><div><dt>GENERATED</dt><dd>${esc(state.dataCheck.generated_at||'—')}</dd></div></dl></section><div class="admin-check-layout"><section class="admin-panel admin-queue-panel"><header class="admin-panel-header"><div><span class="admin-kicker">REVIEW QUEUE</span><h2>Issues requiring attention</h2><p>${issueCount?'每一行都提供详情、修复或确认入口。':'健康状态下队列保持为空。'}</p></div><span class="admin-panel-count" data-health-count>${issueCount} ${issueCount===1?'issue':'issues'}</span></header>${dataCheckSurfaceHtml(rows,{acknowledged:state.dataCheck.acknowledged_count||0})}</section><aside class="admin-panel admin-check-aside"><span class="admin-kicker">ARCHIVE HEALTH</span><h2>One local source.<br>Two safe actions.</h2><p>Cloud Sync 负责准备和校验只读副本；Data Check 负责定位本地结构问题。它们共享上下文，但职责不重叠。</p><div class="admin-route-note"><span>LOCAL JSON</span><i></i><span>REVIEW</span><i></i><span>SYNC</span></div><button class="admin-button admin-button-primary" data-tools-panel="sync">Open Cloud Sync <span>→</span></button></aside></div></section>`;
  }catch(error){finishGuardianIntent(guardianCheckId,'error');emitGuardianIntent('needs-review',{message:error.message||'Data Check is unavailable'},{id:'data-check-page-error'});main.innerHTML=`<div class="loading-page"><h2>Data Check unavailable</h2><p>${esc(error.message)}</p></div>`}
}

function openRealIssue(index){
  const issue=state.dataCheck?.issues?.[index];if(!issue)return;
  const custom=issueIsCustomIdentity(issue);
  const detail=$('[data-data-check-detail]');
  if(state.dataCheckOverlayOpen&&detail){detail.hidden=false;detail.innerHTML=`<button class="data-check-detail-close" data-data-check-detail-close aria-label="关闭问题详情">×</button><span class="severity ${esc(String(issue.severity).toLowerCase())}">${esc(issue.severity)}</span><h3>问题详情</h3><div class="detail-list"><div class="detail-row"><label>日期</label><div>${esc(issue.date)}</div></div><div class="detail-row"><label>区域</label><div>${esc(issue.area)}</div></div><div class="detail-row"><label>具体问题</label><div>${esc(issue.issue)}</div></div><div class="detail-row"><label>建议处理</label><div>${esc(issue.action)}</div></div></div><div class="modal-actions"><button class="btn" data-issue-ack="${index}">确认并隐藏</button><button class="btn btn-primary" data-issue-repair="${index}" data-repair-action="${custom?'dictionary-custom':'editor'}">${custom?'去整理 CUSTOM 动作':'前往处理'} →</button></div>`;return}
  modal('问题详情',`<span class="severity ${esc(String(issue.severity).toLowerCase())}">${esc(issue.severity)}</span><div class="detail-list"><div class="detail-row"><label>日期</label><div>${esc(issue.date)}</div></div><div class="detail-row"><label>区域</label><div>${esc(issue.area)}</div></div><div class="detail-row"><label>具体问题</label><div>${esc(issue.issue)}</div></div><div class="detail-row"><label>建议处理</label><div>${esc(issue.action)}</div></div></div>`,{actions:`<button class="btn" data-issue-ack="${index}">确认并隐藏</button><button class="btn btn-primary" data-issue-repair="${index}" data-repair-action="${custom?'dictionary-custom':'editor'}">${custom?'去整理 CUSTOM 动作':'前往处理'} →</button>`});
}

function repairIssue(index,action='editor'){
  const issue=state.dataCheck?.issues?.[index];if(!issue)return;
  closeDataCheckOverlay();state.repairReturn=true;
  if(action==='cloud'){navigate('cloud-sync');return}
  if(action==='record'){recordDetail(issue.date);return}
  if(action==='raw'){recordDetail(issue.date);return}
  if(action==='dictionary-custom'){state.dictionaryQuery='CUSTOM_';navigate('dictionary');return}
  if(action==='dictionary'){state.dictionaryQuery=issue.movement_name||issue.search_term||'';navigate('dictionary');return}
  if(['body','diet','training'].includes(issue.target_type)){
    const rows={body:state.body,diet:state.diet,training:state.training}[issue.target_type]||[];
    const recordIndex=rows.findIndex(row=>String(row.id||'')===String(issue.target_id||'')||(dateOf(row)===issue.date&&!issue.target_id));
    if(recordIndex>=0){realRecordDetail(issue.target_type,recordIndex);return}
    navigate(issue.target_type);return;
  }
  if(issue.target_type==='movement'){
    const movement=state.movements.find(row=>String(row.movement_id)===String(issue.movement_id));
    if(movement){loadMovementFocus(movement.movement_id);return}
    navigate('movements');return;
  }
  if(issue.target_type==='dictionary'){navigate('dictionary');return}
  if(issue.target_type==='raw'){recordDetail(issue.date);return}
  navigate(issue.area==='Diet'?'diet':issue.area==='Training'?'training':'body');
}

async function acknowledgeRealIssue(index){
  const issue=state.dataCheck?.issues?.[index];if(!issue)return;
  try{await postApi('/api/data-check/acknowledge',{issue_key:issue.issue_key});state.dataCheck=await api('/api/data-check');await loadArchiveHealth();if(state.dataCheckOverlayOpen){if((state.dataCheck.issues||[]).length===0||state.archiveHealth?.status==='OK'||Number(state.archiveHealth?.issue_count||0)<=0)closeDataCheckOverlay();else renderDataCheckOverlay(state.dataCheck)}else if(state.view==='checks')await checksPage();showToast('该提示已确认并隐藏。')}catch(error){showToast(error.message||'确认失败。')}
}

async function undoLastWebWrite(){
  if(!window.confirm('确定撤销最近一次保存或编辑吗？\n当前数据库和动作词典会一起恢复。'))return;
  try{await postApi('/api/undo',{});invalidateMovementUsage();await refreshWebState();navigate('quick');showToast('最近一次写入已撤销。')}catch(error){showToast(error.message||'撤销失败。')}
}

const bodyPartThemes={
  shoulders:{id:'shoulders',labelCn:'肩',labelEn:'SHOULDERS',displayTitle:'Shoulder Training Records',subtitle:'抬升、外展与控制感：集中回看肩部训练的近期变化。',accent:'#d49a27',accentSoft:'#f2d88b',accentDeep:'#6d4708',glow:'rgba(212,154,39,.2)',backgroundGradient:'radial-gradient(circle at 18% 10%,rgba(229,177,56,.23),transparent 36%)',motif:'body-themes-v2/shoulders.png',personality:'lifted',keywords:['肩','肩部','肩手臂','三角肌','后束','中束','推肩','侧平举','y举','shoulder','delts'],emptyStateTitle:'肩部轨迹仍待建立',emptyStateDescription:'下一次包含肩部动作的训练保存后，会自动出现在这里。'},
  chest:{id:'chest',labelCn:'胸',labelEn:'CHEST',displayTitle:'Chest Training Records',subtitle:'向前、展开与力量输出：聚合胸部训练和相关推举记录。',accent:'#c86454',accentSoft:'#efb9ae',accentDeep:'#712b22',glow:'rgba(200,100,84,.19)',backgroundGradient:'radial-gradient(circle at 18% 10%,rgba(205,96,78,.21),transparent 36%)',motif:'body-themes-v2/chest.png',personality:'expansive',keywords:['胸','胸部','胸肩','卧推','推胸','飞鸟','夹胸','chest','bench','pec','fly'],emptyStateTitle:'胸部记录尚未形成',emptyStateDescription:'保存卧推、推胸或飞鸟训练后，这里会开始形成专属档案。'},
  back:{id:'back',labelCn:'背',labelEn:'BACK',displayTitle:'Back Training Records',subtitle:'宽度、深度与稳定控制：整理下拉、划船和拉背训练。',accent:'#34776f',accentSoft:'#afd6cc',accentDeep:'#16463f',glow:'rgba(52,119,111,.2)',backgroundGradient:'radial-gradient(circle at 18% 10%,rgba(52,119,111,.21),transparent 36%)',motif:'body-themes-v2/back.png',personality:'structured',keywords:['背','背部','引体','下拉','划船','高拉','拉背','back','row','pulldown','pull-up'],emptyStateTitle:'背部训练档案为空',emptyStateDescription:'引体、下拉或划船记录会在保存后自动归入这个主题。'},
  legs:{id:'legs',labelCn:'腿',labelEn:'LEGS',displayTitle:'Leg Training Records',subtitle:'稳定、承重与地面力量：集中呈现下肢训练记录。',accent:'#8065a8',accentSoft:'#d5c5e8',accentDeep:'#44305f',glow:'rgba(128,101,168,.2)',backgroundGradient:'radial-gradient(circle at 18% 10%,rgba(128,101,168,.2),transparent 36%)',motif:'body-themes-v2/legs.png',personality:'grounded',keywords:['腿','腿部','股四','股二','腿屈伸','腿弯举','坐蹬','深蹲','leg','squat','extension','hamstring'],emptyStateTitle:'腿部力量轨迹尚未开始',emptyStateDescription:'下肢训练保存后，会在这里建立稳定的历史记录。'},
  arms:{id:'arms',labelCn:'手臂',labelEn:'ARMS',displayTitle:'Arm Training Records',subtitle:'紧凑、专注与节奏：回看二头、三头和手臂辅助训练。',accent:'#3f86a2',accentSoft:'#b8dce8',accentDeep:'#1d4e61',glow:'rgba(63,134,162,.19)',backgroundGradient:'radial-gradient(circle at 18% 10%,rgba(63,134,162,.2),transparent 36%)',motif:'body-themes-v2/arms.png',personality:'rhythmic',keywords:['手臂','二头','三头','弯举','下压','臂屈伸','biceps','triceps','curl','pushdown'],emptyStateTitle:'手臂训练尚无记录',emptyStateDescription:'二头、三头或手臂辅助动作保存后会自动归档到这里。'},
};

const bodyPartOrder=['shoulders','chest','back','legs','arms'];
const normalizeTrainingText=value=>String(value??'').normalize('NFKC').toLowerCase().replace(/\s+/g,'');
function trainingMovementTokens(record){return String(value(record,'Standardized Summary')||'').split(/[；;，,|\n]/).map(token=>token.replace(/^第?\s*\d+\s*(?:个动作)?\s*[:：.]?\s*/,'').trim()).filter(Boolean)}
const movementDefinitions=()=>state.dictionary.length?state.dictionary:state.movements;
const movementNames=definition=>[definition.display_name,definition.english_name,...(definition.aliases||[])].filter(Boolean);
function movementDefinitionForToken(token){const normalized=normalizeTrainingText(token);if(!normalized)return null;const candidates=movementDefinitions().flatMap(definition=>movementNames(definition).map(name=>({definition,name:normalizeTrainingText(name)}))).filter(item=>item.name).sort((a,b)=>b.name.length-a.name.length);return candidates.find(item=>item.name===normalized)?.definition||candidates.find(item=>normalized.includes(item.name)||item.name.includes(normalized))?.definition||null}
function bodyPartIdForGroup(group){const normalized=normalizeTrainingText(group);if(/shoulder|delts|肩/.test(normalized))return'shoulders';if(/chest|pec|胸/.test(normalized))return'chest';if(/back|pull|背/.test(normalized))return'back';if(/legs?|lower|quad|hamstring|腿|股/.test(normalized))return'legs';if(/arms?|biceps|triceps|手臂|二头|三头/.test(normalized))return'arms';return null}
function recordBodyParts(record){const parts=new Set();for(const token of trainingMovementTokens(record)){const definition=movementDefinitionForToken(token),part=bodyPartIdForGroup(definition?.muscle_group);if(part)parts.add(part)}const split=normalizeTrainingText(value(record,'Split','split'));for(const id of bodyPartOrder){const theme=bodyPartThemes[id];if(theme.keywords.some(keyword=>split.includes(normalizeTrainingText(keyword))))parts.add(id)}if(!parts.size){const fallback=normalizeTrainingText([value(record,'title','Title'),value(record,'Notes','notes'),value(record,'Raw Record','raw'),value(record,'detail','Detail')].join(' '));for(const id of bodyPartOrder){if(bodyPartThemes[id].keywords.some(keyword=>fallback.includes(normalizeTrainingText(keyword))))parts.add(id)}}return parts}
function matchBodyPart(record,theme){return recordBodyParts(record).has(theme.id)}
function trainingTopic(record){return String(value(record,'Split','split','Training','title','Title')||'')}
function matchTrainingTheme(record,theme){const topic=normalizeTrainingText(trainingTopic(record));return theme.keywords.some(keyword=>topic.includes(normalizeTrainingText(keyword)))}
function filterRecordsByBodyPart(records,bodyPart=state.selectedBodyPart){const theme=bodyPartThemes[bodyPart];return theme?records.filter(record=>matchTrainingTheme(record,theme)):records}
function themeMovementData(record,theme){const tokens=trainingMovementTokens(record).filter(token=>bodyPartIdForGroup(movementDefinitionForToken(token)?.muscle_group)===theme.id),notes=[];let include=false;for(const part of String(value(record,'Notes')||'').split(/[；;]/)){const segment=part.trim();if(!segment)continue;const separator=segment.search(/[：:]/);if(separator>=0){const prefix=segment.slice(0,separator).trim(),definition=movementDefinitionForToken(prefix);include=bodyPartIdForGroup(definition?.muscle_group)===theme.id}else if(!notes.length){include=false}if(include)notes.push(segment)}return {tokens,notes}}
function trainingRowsForTheme(themeId=state.selectedBodyPart){return filterRecordsByBodyPart(state.training,themeId)}
function getLatestSession(records){return [...records].sort((a,b)=>dateOf(b).localeCompare(dateOf(a)))[0]||null}
function extractMovementStats(records,theme){const frequencies=new Map();for(const record of records){for(const token of trainingMovementTokens(record)){const definition=movementDefinitionForToken(token),part=bodyPartIdForGroup(definition?.muscle_group);if(theme&&part!==theme.id)continue;const name=definition?.display_name||token,key=definition?.movement_id||normalizeTrainingText(name),current=frequencies.get(key)||{name,count:0};current.count++;frequencies.set(key,current)}}return [...frequencies.values()].sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name,'zh-CN'))}
function getTopMovements(records,theme,limit=4){return extractMovementStats(records,theme).slice(0,limit).map(item=>[item.name,item.count])}
function buildTrainingIndex(records){return bodyPartOrder.map(id=>{const theme=bodyPartThemes[id],rows=filterRecordsByBodyPart(records,id);return {id,theme,count:rows.length,last:getLatestSession(rows)}}).sort((a,b)=>b.count-a.count||bodyPartOrder.indexOf(a.id)-bodyPartOrder.indexOf(b.id))}
function bodyPartStats(theme){const rows=filterRecordsByBodyPart(state.training,theme.id),movementStats=extractMovementStats(rows,theme);return {rows,count:rows.length,last:getLatestSession(rows),movementCount:movementStats.length,movements:movementStats.slice(0,4).map(item=>[item.name,item.count])}}
function trainingThemeStyle(theme){return theme?`--training-accent:${theme.accent};--training-accent-soft:${theme.accentSoft};--training-accent-deep:${theme.accentDeep};--training-glow:${theme.glow};--training-bg-gradient:${theme.backgroundGradient};--training-art:url('assets/${theme.motif}')`:''}
function bodyPartThemeControls(){return `<section class="body-theme-deck material-floating" aria-label="按训练部位查看记录"><div class="body-theme-deck-head"><div><span class="eyebrow">TRAINING BODY MAP</span><h2>Connected training archives.</h2></div><button class="theme-overview material-control interactive-press ${state.selectedBodyPart?'':'is-active'}" data-training-theme="overview">ALL RECORDS <b>${state.training.length}</b></button></div><div class="body-theme-controls">${bodyPartOrder.map((id,index)=>{const theme=bodyPartThemes[id],stats=bodyPartStats(theme),active=state.selectedBodyPart===id;return `<button class="body-theme-control material-frosted interactive-lift interactive-press ${active?'is-active':''}" data-training-theme="${id}" data-personality="${theme.personality}" style="--theme-index:${index};${trainingThemeStyle(theme)}"><img src="assets/${theme.motif}" alt="" aria-hidden="true"><span class="theme-cn">${theme.labelCn}</span><span class="theme-en">${theme.labelEn}</span><span class="theme-meta"><b>${stats.count}</b> sessions · ${stats.movementCount} movements</span><span class="theme-last">${stats.last?`Latest ${esc(dateOf(stats.last))}`:'Awaiting first record'}</span></button>`}).join('')}</div></section>`}
function trainingSidePanel(theme){if(!theme){const index=buildTrainingIndex(state.training);return `<aside class="training-index material-frosted"><span class="eyebrow">TRAINING INDEX</span><h2>${state.training.length}<small> logged sessions</small></h2><p>Sessions grouped through the maintained movement dictionary.</p><div class="split-index">${index.map((item,position)=>`<button data-training-theme="${item.id}"><span>0${position+1}</span><strong>${item.theme.labelCn}</strong><b>${item.count}</b></button>`).join('')}</div><div class="training-index-note">SELECT A BODY ARCHIVE</div></aside>`}const stats=bodyPartStats(theme),latest=stats.last,recentNote=latest?themeMovementData(latest,theme).notes.join('；'):'';return `<aside class="training-index training-focus-panel material-frosted"><span class="eyebrow">${theme.labelEn} / FOCUS PANEL</span><h2>${stats.count}<small> related sessions</small></h2><div class="focus-metrics"><span><small>LAST SESSION</small><strong>${esc(latest?dateOf(latest):'—')}</strong></span><span><small>MOVEMENTS</small><strong>${stats.movementCount}</strong></span></div><div class="focus-movements"><span class="eyebrow">FREQUENT SIGNALS</span>${stats.movements.map(([name,count],index)=>`<div><span>0${index+1}</span><strong>${esc(name)}</strong><b>${count}</b></div>`).join('')||'<p>尚无结构化动作摘要。</p>'}</div><div class="focus-note"><span class="eyebrow">RECENT NOTE</span><p>${esc(short(recentNote||'最近一次相关动作没有附加备注。',120))}</p></div>${latest?`<button class="focus-open" data-detail="training" data-index="${state.training.indexOf(latest)}">Open latest detail <span>→</span></button>`:''}</aside>`}

function focusTrainingRoute(){
  const date=state.routeParams?.date||'',movementId=String(state.routeParams?.movement_id||'');if(!date&&!movementId)return;const card=[...$$('#session-grid [data-training-date]')].find(row=>!date||row.dataset.trainingDate===date);if(!card){window.scrollTo(0,0);return}const movement=movementId?[...card.querySelectorAll('[data-training-movement-id]')].find(row=>row.dataset.trainingMovementId===movementId):null,target=movement||card;target.scrollIntoView({behavior:'smooth',block:movement?'center':'start'});if(movement){movement.classList.add('is-context-focus');movement.addEventListener('animationend',()=>movement.classList.remove('is-context-focus'),{once:true})}
}
function trainingPage(){const theme=bodyPartThemes[state.selectedBodyPart]||null,query=state.trainingQuery||'',order=state.trainingOrder||'recent',toolbar=`<div class="toolbar training-theme-toolbar"><input class="control search" id="training-search" value="${esc(query)}" autocomplete="off" spellcheck="false" placeholder="Search training theme or date..."><select class="control" id="training-order"><option value="recent" ${order==='recent'?'selected':''}>Newest first</option><option value="oldest" ${order==='oldest'?'selected':''}>Oldest first</option></select></div>`;main.innerHTML=`<section class="page training-archive training-theme-page" data-training-theme="${theme?.id||'overview'}" style="${trainingThemeStyle(theme)}"><div class="training-atmosphere" aria-hidden="true"></div><div class="training-theme-header"><div><span class="eyebrow">04 / ${theme?`${theme.labelEn} ARCHIVE`:'TRAINING ARCHIVE'}</span><h1>${esc(theme?.displayTitle||'Training Records')}</h1><p>${esc(theme?.subtitle||'Complete movement and set records, with structured detail available for editing.')}</p></div>${theme?`<div class="training-header-tools"><button class="back-overview" data-training-theme="overview">← Back to overview</button>${toolbar}</div>`:''}</div>${bodyPartThemeControls()}<div class="training-stage"><div class="training-main">${theme?'':toolbar}<div id="session-grid" class="session-grid"></div>${pager()}</div>${trainingSidePanel(theme)}</div></section>`;bindTrainingControls();renderTraining(query);requestAnimationFrame(()=>$('.training-theme-page')?.classList.add('is-entered'))}

function bindTrainingControls(){const search=$('#training-search'),order=$('#training-order');if(search)search.addEventListener('input',event=>{state.trainingQuery=event.currentTarget.value;renderTraining(state.trainingQuery)});if(order)order.addEventListener('change',event=>{state.trainingOrder=event.currentTarget.value;renderTraining(state.trainingQuery||'')})}

function trainingTopicMatch(record,query){const raw=String(query??'').trim();if(!raw)return true;const terms=raw.split(/\s+/).map(compactSearch).filter(Boolean),topic=compactSearch(trainingTopic(record));if(terms.every(term=>topic.includes(term)))return true;const wanted=dateParts(raw),actual=dateParts(dateOf(record));return Boolean(wanted&&actual&&wanted[0]===actual[0]&&wanted[1]===actual[1])}
function clearPreviousHover(){clearTimeout(state.hoverTimer);state.hoverTimer=null;state.hoverNode?.querySelector('.previous-preview')?.remove();state.hoverNode=null}
function clearMovementIndexPreviousPreview(){clearTimeout(state.movementIndexPreviewTimer);state.movementIndexPreviewTimer=null;state.movementIndexPreviewNode?.classList.remove('is-previewing');state.movementIndexPreviewNode=null;$('.movement-index-previous-preview')?.remove()}
function renderMovementIndexPreviousPreview(tile){if(tile!==state.movementIndexPreviewNode||!tile.isConnected)return;const movementId=tile.dataset.indexPreviewMovementId,latest=state.movementUsage[movementId]?.payload?.progress_history?.[0];if(!latest)return;const sets=(latest.sets_lines||[]).filter(Boolean).slice(0,2),note=String(latest.notes||'').trim(),rect=tile.getBoundingClientRect(),width=Math.min(310,window.innerWidth-32);let left=Math.min(window.innerWidth-width-16,Math.max(16,rect.left+rect.width/2-width/2)),top=rect.bottom+10;const estimatedHeight=sets.length&&note?190:160;if(top+estimatedHeight>window.innerHeight)top=Math.max(16,rect.top-estimatedHeight-10);document.body.insertAdjacentHTML('beforeend',`<aside class="movement-index-previous-preview" role="tooltip" style="left:${Math.round(left)}px;top:${Math.round(top)}px;width:${Math.round(width)}px"><span class="eyebrow">LAST SESSION</span><div class="movement-index-preview-head"><strong>${esc(latest.date||'Latest record')}</strong><small>${esc(tile.querySelector('strong')?.textContent||'Movement')}</small></div><div class="movement-index-preview-sets">${sets.length?sets.map(line=>`<span>${esc(line)}</span>`).join(''):'<span>No structured set summary</span>'}</div>${note?`<p>${esc(short(note,72))}</p>`:''}</aside>`);tile.classList.add('is-previewing')}
function scheduleMovementIndexPreviousPreview(tile){clearMovementIndexPreviousPreview();state.movementIndexPreviewNode=tile;state.movementIndexPreviewTimer=setTimeout(()=>renderMovementIndexPreviousPreview(tile),750)}
function trainingMovementRefs(record){const refs=Array.isArray(record.movement_refs)?record.movement_refs:[];if(refs.length)return refs;return trainingMovementTokens(record).map((display_name,order)=>({movement_id:'',display_name,order:order+1,sets_lines:[],notes:'',is_linkable:false}))}
function archiveProgressControl(ref){const movementId=String(ref.movement_id||''),historyId=String(ref.history_id||'');if(!movementId||!historyId)return '<span class="instance-progress-note is-unrecognized">动作尚未识别，仅保留原始记录</span>';const included=!Boolean(ref.exclude_from_progress);return `<label class="archive-progress-toggle" title="${included?'关闭后仅保留训练记录':'开启后恢复成长轨迹'}"><input type="checkbox" data-instance-progress-toggle data-movement-id="${esc(movementId)}" data-history-id="${esc(historyId)}" ${included?'checked':''}><span>${included?'计入成长轨迹':'仅保留训练记录'}</span></label>`}
function trainingMovementRow(ref,recordDate){const movementId=String(ref.movement_id||''),linkable=Boolean(ref.is_linkable&&movementId),name=ref.display_name||ref.english_name||movementId||'Unmapped movement',sets=(ref.sets_lines||[]).filter(Boolean),body=`<span class="training-movement-order">${String(Number(ref.order)||0).padStart(2,'0')}</span><span class="training-movement-copy"><strong>${esc(name)}</strong><small>${sets.length?esc(sets.join(' · ')):'No structured sets'}</small>${ref.notes?`<em>${esc(short(ref.notes,90))}</em>`:''}</span>${linkable?'<span class="training-movement-direction" aria-hidden="true">↗</span>':''}`,row=linkable?`<button type="button" class="training-movement-row is-linkable" data-select-movement-id="${esc(movementId)}" data-training-movement-id="${esc(movementId)}" data-previous-movement-id="${esc(movementId)}" data-current-date="${esc(recordDate)}">${body}</button>`:`<div class="training-movement-row">${body}</div>`;return `<div class="training-movement-row-shell ${ref.exclude_from_progress?'is-excluded':''}">${row}${archiveProgressControl(ref)}</div>`}
function renderPreviousPreview(link,history){const previous=history?.[0];if(!previous||link!==state.hoverNode)return;const sets=(previous.sets_lines||[]).slice(0,2);if(!sets.length)return;const current=new Date(`${link.dataset.currentDate}T00:00:00`),prior=new Date(`${previous.date}T00:00:00`),days=Math.max(0,Math.round((current-prior)/86400000));link.insertAdjacentHTML('beforeend',`<span class="previous-preview" role="tooltip"><span class="eyebrow">PREVIOUS</span><strong>${sets.map(esc).join('<br>')}</strong><small>${days?`${days} days earlier`:esc(previous.date||'')}</small></span>`)}
function schedulePreviousPreview(link){clearPreviousHover();state.hoverNode=link;state.hoverTimer=setTimeout(async()=>{if(link!==state.hoverNode)return;try{const payload=await api(`/api/movement-history?movement_id=${encodeURIComponent(link.dataset.previousMovementId)}&before_date=${encodeURIComponent(link.dataset.currentDate)}&limit=1`);renderPreviousPreview(link,payload.history||[])}catch(_error){}},400)}
function renderTraining(q=state.trainingQuery??$('#training-search')?.value??''){clearPreviousHover();const theme=bodyPartThemes[state.selectedBodyPart]||null;let rows=trainingRowsForTheme().filter(record=>trainingTopicMatch(record,q));if((state.trainingOrder||$('#training-order')?.value||'recent')==='oldest')rows=[...rows].reverse();const target=$('#session-grid');if(!target)return;target.innerHTML=rows.slice(0,20).map((record,index)=>{const refs=trainingMovementRefs(record),recordDate=dateOf(record),note=String(value(record,'Notes')||''),stored=value(record,'No.'),fallback=state.training.length-state.training.indexOf(record),sessionNo=stored==='-'?fallback:stored,focusIds=refs.filter(ref=>ref.is_linkable&&ref.movement_id).map(ref=>ref.movement_id).join(',');return `<article class="session session-slip training-theme-slip" data-training-date="${esc(recordDate)}" data-training-movement-ids="${esc(focusIds)}" style="--record-index:${index}"><div class="session-number">${esc(String(sessionNo).padStart(2,'0'))}</div><div class="rail-head"><h3>${esc(recordDate)}</h3></div><p class="session-split">${esc(value(record,'Split'))}</p><div class="session-facts"><span>${refs.length} movements</span><span>Complete movement and set archive</span></div><div class="training-movement-list">${refs.map(ref=>trainingMovementRow(ref,recordDate)).join('')}</div>${note?`<p class="session-note">${esc(short(note,120))}</p>`:''}<button class="record-open" data-detail="training" data-index="${state.training.indexOf(record)}">Open structured detail</button></article>`}).join('')||`<section class="training-empty"><span class="empty-mark">${esc(theme?.labelCn||'ALL')}</span><h2>${esc(theme?.emptyStateTitle||'No matching training sessions')}</h2><p>${esc(theme?.emptyStateDescription||'Adjust the search or return to all records.')}</p><button data-training-theme="overview">View all records</button></section>`;focusTrainingRoute()}
function layoutTrainingGrid(){const grid=$('#session-grid');if(!grid)return;const styles=getComputedStyle(grid),rowHeight=parseFloat(styles.gridAutoRows)||4,gap=parseFloat(styles.rowGap)||0;[...grid.children].forEach(card=>{card.style.gridRowEnd='auto'});[...grid.children].forEach(card=>{const span=Math.ceil((card.getBoundingClientRect().height+gap)/(rowHeight+gap));card.style.gridRowEnd=`span ${Math.max(1,span)}`})}
const renderTrainingWithDenseLayout=renderTraining;
renderTraining=function(...args){renderTrainingWithDenseLayout(...args);requestAnimationFrame(()=>{layoutTrainingGrid();if(state.routeParams?.date||state.routeParams?.movement_id)focusTrainingRoute()})};

function toolsPage(){const panel=state.routeParams?.panel||'overview';if(panel==='export'){analysisExportProtocolPage();$('.export-page')?.insertAdjacentHTML('afterbegin','<button class="tools-route-back" data-tools-panel="overview">← Tools</button>');return}if(panel==='sync'){cloudSyncPage().then(()=>$('.cloud-sync-page')?.insertAdjacentHTML('afterbegin','<button class="tools-route-back" data-tools-panel="overview">← Tools</button>'));return}main.innerHTML=`<section class="page tools-page"><header class="tools-hero"><div><span class="eyebrow">PERSONAL ARCHIVE / UTILITIES</span><h1>Tools</h1></div><p>维护本地档案、只读云副本与数据健康。三个入口共享同一份本地事实，但不会彼此替代。</p></header><section class="tools-workbench material-floating"><aside class="tools-ledger"><span class="tools-ledger-stamp" aria-hidden="true">08</span><span class="eyebrow">UTILITY DESK / LOCAL FIRST</span><h2>One archive.<br><em>Three careful exits.</em></h2><p>正式记录始终留在本地 JSON。这里负责携带、同步与检查，不创建第二份事实来源。</p><nav class="tools-ledger-index" aria-label="Tool index"><span>06 / Analysis Export</span><span>07 / Cloud Sync</span><span>08 / Data Health</span></nav><dl><div><dt>SOURCE</dt><dd>Local archive</dd></div><div><dt>NETWORK</dt><dd>Only when syncing</dd></div><div><dt>HEALTH</dt><dd data-tools-health-status>正在检查</dd></div></dl></aside><div class="tools-actions" aria-label="档案工具"><button class="tool-row tool-row-export" data-tools-panel="export"><span class="tool-row-number">06</span><span class="tool-row-copy"><span class="eyebrow">EXPORT DESK / V1.1</span><strong>Export</strong><small>将 Body、Diet、Training 与 Movement 整理为 Markdown / JSON，供分析与归档使用。</small><span class="tool-row-tags"><i>JSON CONTRACT</i><i>V1.1</i><i>LOCAL ONLY</i><i>NEW</i></span></span><b>进入导出 <span>→</span></b></button><button class="tool-row tool-row-sync" data-tools-panel="sync"><span class="tool-row-number">07</span><span class="tool-row-copy"><span class="eyebrow">READ-ONLY REPLICA</span><strong>Sync</strong><small>手动生成 Payload、上传 CloudBase 并校验只读副本；本地数据始终优先。</small><span class="tool-row-tags"><i>MANUAL</i><i>VERIFIED</i><i>CLOUDBASE</i></span></span><b>打开同步 <span>→</span></b></button><button class="tool-row tool-row-health" data-tools-panel="health"><span class="tool-row-number">08</span><span class="tool-row-copy"><span class="eyebrow">SILENT HEALTH</span><strong>Data Health</strong><small>仅在需要时查看问题、进入对应记录并确认处理；正常状态保持安静。</small><span class="tool-row-tags"><i>CONTEXTUAL</i><i>NON-DESTRUCTIVE</i></span></span><b>查看健康 <span>→</span></b></button></div></section><footer class="tools-footnote"><span>FITNESS LEDGER / MAINTENANCE SURFACE</span><p>工具不会修改同步架构，也不会让云端或小程序成为正式数据源。</p></footer></section>`;renderArchiveHealth();if(panel==='health')queueMicrotask(openDataCheckOverlay)}
function analysisExportPage(){
  main.innerHTML=`<section class="page export-page"><header class="export-hero"><span class="eyebrow">08 / PORTABLE CONTEXT</span><h1>Analysis<br>Export.</h1><p>生成供 ChatGPT 或其他分析工具阅读的 Markdown 与 JSON。不会上传数据。</p></header><section class="intelligent-export-candidate"><div class="intelligent-export-head"><span class="eyebrow">DETERMINISTIC REVIEW / NO MODEL</span><h2>Describe the<br><em>question.</em></h2><p>先让 Core 显示它理解的范围，再决定是否下载。当前候选不会调用 Ollama 或任何网络模型。</p></div><div class="intelligent-export-body"><form id="intelligent-export-form" class="intelligent-export-console"><label for="intelligent-export-request">自然语言需求<textarea id="intelligent-export-request" name="request" rows="4" placeholder="例如：分析最近一个月的饮食和体重"></textarea></label><div class="intelligent-scenarios" aria-label="固定 Review 场景"><span class="eyebrow">REVIEW SCENARIOS</span><div>${INTELLIGENT_REVIEW_SCENARIOS.map((item,index)=>`<button type="button" class="scenario-chip" data-intelligent-scenario="${index}" title="${esc(item.label)}">R${index+1} · ${esc(item.short)}</button>`).join('')}</div></div><button class="btn btn-primary" type="button" data-intelligent-review>Preview interpretation <span>→</span></button><small class="intelligent-export-note">READ ONLY · NO SAVE · NO CLOUD · MODEL CALLS 0</small></form><div id="intelligent-export-result" class="intelligent-export-result" data-status="idle"><span class="eyebrow">CORE REVIEW / WAITING</span><h3>Make the scope<br>visible first.</h3><p>输入一条需求，查看日期、领域、Notes、动作和 Raw 范围。澄清、冲突或拒绝不会提供下载按钮。</p></div></div></section><section class="export-workbench"><form id="export-form" class="export-console"><span class="eyebrow">BUILD RANGE / MANUAL</span><label>范围<select name="days"><option value="7">最近 7 天</option><option value="14" selected>最近 14 天</option><option value="30">最近 30 天</option></select></label><label>开始日期（可选）<input type="date" name="start"></label><label>结束日期（可选）<input type="date" name="end"></label><label class="export-check"><input type="checkbox" name="include_raw_preview"> 包含原始输入的 180 字预览</label><button class="btn btn-primary" data-build-export>Generate export <span>→</span></button><p>LOCAL ONLY · NO NETWORK UPLOAD</p></form><div class="export-result" id="export-result" data-status="idle"><div class="export-result-orbit" aria-hidden="true"></div><span class="eyebrow">EXPORT CAPSULE / READY</span><h2>Ready to<br>prepare.</h2><p>也可以手动指定日期范围，生成现有 Body、Diet、Training、Movement 与 Data Quality 档案。</p><div class="export-manifest"><span>BODY</span><span>DIET</span><span>TRAINING</span><span>MOVEMENT</span><span>QUALITY</span></div></div></section></section>`;
  $('.export-console')?.insertAdjacentHTML('beforeend','<button type="button" class="cloud-sync-entry" data-cloud-sync-open><span>Cloud Sync</span><small>生成只读副本与校验报告 →</small></button>');
  requestAnimationFrame(()=>$('.export-page')?.classList.add('is-entered'));
}

