function renderAnalysisExportProtocolResult(payload){const target=$('#analysis-export-protocol-result');if(!target)return;const status=payload?.status||'invalid_request',errors=analysisExportErrorItems(payload);if(status==='valid'){const request=payload.normalized_request||state.analysisExportProtocolRequest||protocolRequestValue();state.analysisExportProtocolRequest=request;state.analysisExportProtocolPreview=null;renderAnalysisExportScope([request],[],'\u5df2\u901a\u8fc7\u8bf7\u6c42\u68c0\u67e5');return}if(status==='preview_ready'){state.analysisExportProtocolPreview=payload;renderAnalysisExportPreview([payload],[payload.normalized_request||state.analysisExportProtocolRequest||protocolRequestValue()]);return}const titles={formal_data_unavailable:'\u6b63\u5f0f\u6570\u636e\u6e90\u6682\u4e0d\u53ef\u7528',safety_blocked:'\u8bf7\u6c42\u88ab\u53ea\u8bfb\u5b89\u5168\u8fb9\u754c\u62e6\u622a',invalid_request:'JSON \u9700\u8981\u4fee\u6539',validation_failed:'JSON \u9700\u8981\u4fee\u6539'};const fallback={formal_data_unavailable:'\u5f53\u524d\u6b63\u5f0f\u6570\u636e\u6e90\u4e0d\u53ef\u7528\uff0c\u8bf7\u7a0d\u540e\u91cd\u8bd5\u3002',safety_blocked:'\u5f53\u524d\u8bf7\u6c42\u89e6\u53d1\u4e86\u53ea\u8bfb\u5b89\u5168\u8fb9\u754c\uff0c\u8bf7\u4fee\u6539\u8bf7\u6c42\u8303\u56f4\u3002',invalid_request:'Validator \u6ca1\u6709\u8fd4\u56de\u5177\u4f53\u8bf4\u660e\uff0c\u8bf7\u68c0\u67e5 Request \u7ed3\u6784\u3002',validation_failed:'Validator \u6ca1\u6709\u8fd4\u56de\u5177\u4f53\u8bf4\u660e\uff0c\u8bf7\u68c0\u67e5 Request \u7ed3\u6784\u3002'};renderAnalysisExportError(titles[status]||'\u9884\u89c8\u4e0d\u53ef\u7528',errors[0]?.message||fallback[status]||'\u5f53\u524d\u8bf7\u6c42\u65e0\u6cd5\u7ee7\u7eed\uff0c\u8bf7\u67e5\u770b\u8fd4\u56de\u7684\u72b6\u6001\u548c\u63d0\u793a\u3002',errors.slice(1))}
