async function exportAnalysisExportProtocol(){const preview=state.analysisExportProtocolPreview,check=$('#analysis-export-confirm'),button=$('[data-analysis-export-confirm]');if(!preview?.confirmation_token){showToast('请先完成 Preview。');return}if(!check?.checked){showToast('请先确认当前范围。');return}try{if(button){button.disabled=true;button.textContent='正在重新校验…'}const result=await postApi('/api/analysis-export/v1/export',{request:preview.normalized_request||state.analysisExportProtocolRequest||protocolRequestValue(),confirmed:true,confirmation_token:preview.confirmation_token,preview_context_id:preview.preview_context_id||''});if(result.status==='bundle_ready')renderFormalSemanticExportResult(result);else renderAnalysisExportError('导出未完成',result.errors?.[0]?.message||'请返回调整范围。')}catch(error){renderAnalysisExportError('导出失败',error.message)}finally{if(button){button.disabled=false;button.innerHTML='确认并下载 <span>→</span>'}}}
async function requestFormalSemanticPreviews(natural){const requests=Array.isArray(natural.requests)&&natural.requests.length?natural.requests:[natural.request],previews=[],previewContextId=natural.preview_context_id||'';for(const request of requests){const preview=await postApi('/api/analysis-export/v1/preview',{request,preview_context_id:previewContextId});if(preview.status!=='preview_ready'){renderFormalSemanticPreview({status:'needs_confirmation',confirmations:['只读 Preview 未通过，未生成数据包。'],errors:preview.errors||preview.preview?.warnings||[],semantic_plan:natural.semantic_plan});return null}previews.push(preview)}state.formalSemanticPreviews=previews;state.formalSemanticPreview={...natural,requests,preview_count:previews.length};renderFormalSemanticPreview(state.formalSemanticPreview);return previews}
async function continueFormalSemanticCandidateSelection(){const input=$('#analysis-export-natural-language'),button=$('[data-analysis-export-candidate-continue]');if(!input)return;const selected=[...document.querySelectorAll('[data-natural-candidate]:checked')].map(item=>item.value).filter(Boolean);if(!selected.length){showToast('请至少选择一个正式动作。');return}try{if(button)button.disabled=true;setAnalysisExportProtocolStage('validate');const natural=await postApi('/api/analysis-export/v1/natural-language/preview',{text:input.value.trim(),selected_movement_ids:selected,supersedes_preview_context_id:state.formalSemanticPreviewContextId||''});state.formalSemanticPreviewContextId=natural.preview_context_id||'';if(natural.status!=='ready'){renderFormalSemanticPreview(natural);return}await requestFormalSemanticPreviews(natural);showToast('已按选定动作准备 Preview。')}catch(error){renderAnalysisExportError('解释失败',error.message)}finally{if(button)button.disabled=false}}
async function exportFormalSemanticDataPackage(){const input=$('#analysis-export-natural-language'),button=analysisExportPrimaryButton();if(!input||state.formalSemanticBusy)return;const text=input.value.trim();if(!text){renderAnalysisExportError('请先描述导出需求','请输入你想导出的数据范围。');input.focus();return}state.formalSemanticBusy=true;state.formalSemanticPreviews=[];state.formalSemanticPreview=null;setAnalysisExportProtocolStage('validate');if(button){button.disabled=true;button.textContent='正在解释…'}try{const natural=await postApi('/api/analysis-export/v1/natural-language/preview',{text,supersedes_preview_context_id:state.formalSemanticPreviewContextId||''});state.formalSemanticPreviewContextId=natural.preview_context_id||'';if(natural.status!=='ready'||!(natural.requests?.length||natural.request)){renderFormalSemanticPreview(natural);return}await requestFormalSemanticPreviews(natural);showToast('范围已准备，请检查右侧范围。')}catch(error){renderAnalysisExportError('解释失败',error.message)}finally{state.formalSemanticBusy=false;if(button){button.disabled=false;analysisExportSetPrimaryLabel(state.formalSemanticPreview?'重新解释':'重新试试')}}}
async function confirmFormalSemanticDataPackage(){const check=$('#analysis-export-confirm'),previews=Array.isArray(state.formalSemanticPreviews)?state.formalSemanticPreviews:[],button=$('[data-analysis-export-confirm]');if(!check?.checked){showToast('请先确认当前范围。');return}if(!previews.length){showToast('请先完成 Preview。');return}try{if(button){button.disabled=true;button.textContent='正在重新校验…'}const results=[];for(const preview of previews){const result=await postApi('/api/analysis-export/v1/export',{request:preview.normalized_request,confirmed:true,confirmation_token:preview.confirmation_token,preview_context_id:preview.preview_context_id||''});if(result.status!=='bundle_ready'){renderAnalysisExportError('确认未通过',result.errors?.[0]?.message||'未生成数据包。');return}results.push(result)}renderFormalSemanticExportResult(results);showToast(`${results.length} 个只读数据包已生成。`)}catch(error){renderAnalysisExportError('导出失败',error.message)}finally{if(button){button.disabled=false;button.innerHTML='确认并下载 <span>→</span>'}}}
function renderFormalSemanticExportResult(result){const target=$('#analysis-export-protocol-result');if(!target)return;const results=Array.isArray(result)?result:[result];target.innerHTML=`<div class="analysis-export-done"><h4>导出数据包已就绪</h4><p>${results.length} 个数据包已生成，正式记录未被修改。</p><div class="analysis-export-download-list">${results.map((item,index)=>{const jsonUrl=`/api/analysis-export/v1/artifact/${encodeURIComponent(item.artifact_id)}?format=json`,markdownUrl=`/api/analysis-export/v1/artifact/${encodeURIComponent(item.artifact_id)}?format=markdown`;return `<div><strong>${results.length>1?`第 ${index+1} 组 ? `:''}${esc(item.record_count)} 条记录</strong><a href="${jsonUrl}" download="fitness-ledger-analysis-bundle-${index+1}.json">下载 JSON</a><a href="${markdownUrl}" download="fitness-ledger-analysis-bundle-${index+1}.md">下载 Markdown</a></div>`}).join('')}</div></div>`;setAnalysisExportProtocolStage('done')}
function analysisExportAdvance(){const root=analysisExportRoot(),stage=state.analysisExportStage;if(!root)return;if(stage==='scope'){if(root.dataset.inputMode==='json'&&!state.analysisExportProtocolPreview){previewAnalysisExportProtocol();return}renderAnalysisExportPreview(state.formalSemanticPreviews||[],state.formalSemanticPreview?.requests||[state.analysisExportProtocolRequest],state.formalSemanticPreview?.semantic_plan||{});return}if(stage==='preview'){if(root.dataset.inputMode==='json')exportAnalysisExportProtocol();else confirmFormalSemanticDataPackage()}}
function analysisExportBack(){analysisExportResetEvidence();analysisExportActiveInput()?.focus()}
