function renderIntelligentExportResult(payload){
  const target=$('#intelligent-export-result');if(!target)return;
  const status=payload?.status||'safe_fallback',explanation=payload?.explanation||{},plan=payload?.plan||{},intent=payload?.intent||{},diagnostics=payload?.diagnostics||{};
  target.dataset.status=status;
  if(status!=='ready'){
    target.innerHTML=`<span class="eyebrow">${esc(status==='safe_fallback'?'SAFE FALLBACK':'CORE RESPONSE')}</span><h3>${esc(payload?.error||'当前请求不能安全形成导出范围。')}</h3><p>没有生成下载内容。原因代码：<code>${esc(payload?.error_code||'NO_SAFE_PLAN')}</code></p><div class="intelligent-meta"><span>MODEL CALLS ${Number(payload?.model_calls||diagnostics.model_call_count||0)}</span><span>READ ONLY</span></div>`;return;
  }
  const range=plan.date_range||{},modules=Array.isArray(plan.selected_modules)?plan.selected_modules:[],fields=plan.selected_fields||{},movements=Array.isArray(plan.selected_movements)?plan.selected_movements:[],notes=Array.isArray(plan.notes_selection)?plan.notes_selection:[],warnings=Array.isArray(plan.missing_data_warnings)?plan.missing_data_warnings:[];
  state.analysisExport=payload.output||{};
  target.innerHTML=`<span class="eyebrow">READY / DETERMINISTIC CORE</span><h3>${esc(explanation.interpreted_goal||'范围已通过 Validator')}</h3><p>${esc(range.resolved_start||'')} → ${esc(range.resolved_end||'')} · ${esc(modules.join(', ')||'未选择模块')}</p><div class="intelligent-selection"><div><b>包含</b><span>${esc(modules.join(' · ')||'—')}</span></div><div><b>动作</b><span>${esc(movements.join(' · ')||'未指定动作')}</span></div><div><b>Notes</b><span>${esc(notes.join(' · ')||'未选择')}</span></div><div><b>估计</b><span>${esc(String(plan.estimated_output_size||'—'))}</span></div></div>${warnings.length?`<p class="intelligent-warning">数据提示：${esc(warnings.join('、'))}</p>`:''}<details class="intelligent-technical"><summary>技术详情（Intent / Plan / Trace）</summary><pre>${esc(JSON.stringify({intent,plan,trace:payload.trace||{},diagnostics},null,2))}</pre></details><div class="export-actions"><button class="export-object is-copy" data-copy-export="markdown"><span>Copy Markdown</span><small>local clipboard</small></button><button class="export-object" data-download-export="markdown"><span>Download .md</span><small>Markdown file</small></button><button class="export-object" data-download-export="json"><span>Download .json</span><small>structured data</small></button></div>`;
}

async function previewIntelligentExport(){const input=$('#intelligent-export-request'),button=$('[data-intelligent-review]'),target=$('#intelligent-export-result');if(!input||!button||!target)return;const request=input.value.trim();if(!request){showToast('请先输入一条分析或导出需求。');input.focus();return}button.disabled=true;button.innerHTML='Reading scope…';target.dataset.status='loading';target.innerHTML='<span class="eyebrow">PARSING / LOCAL CORE</span><h3>Making the scope visible.</h3><p>不会写入记录，也不会调用模型。</p>';try{const payload=await postApi('/api/intelligent-export/preview',{request});renderIntelligentExportResult(payload)}catch(error){renderIntelligentExportResult({status:'safe_fallback',error:error.message,error_code:'REQUEST_FAILED',model_calls:0})}finally{button.disabled=false;button.innerHTML='Preview interpretation <span>→</span>'}}

